import type { AdaptationContext, AppliedAdaptation } from '../types.ts';
import { generateWeek } from './generate-week.ts';

/**
 * A new Block's week of Sessions from `startsOn`, generated by rules over the person's current
 * basis, replacing the week's unfinished Sessions nothing was done in. `null` when there is
 * nothing to replace or the library cannot fill the week.
 */
export function regenerateWeek(
  context: AdaptationContext,
  {
    weekInBlock,
    startsOn,
    rirBoost = 0,
  }: { weekInBlock: number; startsOn: string; rirBoost?: number },
): AppliedAdaptation | null {
  const replaced = context.sessions.filter((session) => !session.finished && !session.started);
  if (replaced.length === 0) return null;
  const week = generateWeek({ ...context.generation, weekInBlock, startsOn, rirBoost });
  if (week === null) return null;
  return {
    block: {
      emphasis: week.emphasis,
      startsOn: week.startsOn,
      weekInBlock: week.weekInBlock,
      limited: week.limited,
    },
    supersedes: replaced.map(({ id }) => id),
    sessions: week.sessions.map((session) => ({ ...session, supersedes: null })),
  };
}
